/**
 * Orval mutator —— 全应用唯一允许触碰 fetch 的位置。
 *
 * 会话：HttpOnly Cookie 由浏览器同源自动携带（无 token 存储）。
 * CSRF：非安全方法从 XSRF-TOKEN cookie 取值回填 X-XSRF-TOKEN 头（SPA 方案）。
 * 信封：后端统一 ApiResponse{code,message,data,traceId}；非 OK code 与 HTTP 错误
 * 一律抛错（错误响应不进 Query 缓存，成功分支即业务数据）。
 */
export class UnauthorizedError extends Error {
  constructor(message = '未登录或登录已过期') {
    super(message);
    this.name = 'UnauthorizedError';
  }
}

export class ApiError extends Error {
  readonly code: string;
  readonly status: number;
  readonly traceId?: string;

  constructor(code: string, status: number, message: string, traceId?: string) {
    super(message);
    this.name = 'ApiError';
    this.code = code;
    this.status = status;
    this.traceId = traceId;
  }
}

interface ApiResponseEnvelope {
  /** 后端业务码：0 表示成功，非 0 为 5 位错误码 */
  code?: number;
  message?: string;
  data?: unknown;
  traceId?: string;
}

const UNSAFE_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);

function csrfToken(): string | null {
  const match = document.cookie.match(/(?:^|;\s*)XSRF-TOKEN=([^;]+)/);
  return match ? decodeURIComponent(match[1]) : null;
}

export async function adminFetch<T>(url: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  if (init.body !== undefined && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }
  const method = (init.method ?? 'GET').toUpperCase();
  if (UNSAFE_METHODS.has(method)) {
    const token = csrfToken();
    if (token) {
      headers.set('X-XSRF-TOKEN', token);
    }
  }

  let response: Response;
  try {
    response = await fetch(url, { ...init, headers, credentials: 'same-origin' });
  } catch {
    throw new ApiError('NETWORK_ERROR', 0, '网络异常，请稍后重试');
  }

  let body: ApiResponseEnvelope | null = null;
  try {
    body = (await response.json()) as ApiResponseEnvelope;
  } catch {
    // 非 JSON 响应（网关错误页等）按 HTTP 状态处理
  }

  if (response.status === 401) {
    throw new UnauthorizedError(body?.message);
  }
  // 204 No Content：后端对幂等写操作（重置密码、吊销设备等）的成功约定，无信封体
  if (response.status === 204) {
    return null as T;
  }
  if (!response.ok || body === null || body.code !== 0) {
    // 业务码统一转成字符串放进入错误对象，便于日志与上报统一处理；
    // 没有业务码（网关错误页等）时退回 HTTP 状态。
    const bizCode = body?.code;
    throw new ApiError(
      bizCode !== undefined && bizCode !== 0 ? String(bizCode) : `HTTP_${response.status}`,
      response.status,
      body?.message ?? `请求失败（HTTP ${response.status}）`,
      body?.traceId,
    );
  }
  return body.data as T;
}
